{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "opencode-op-loading",
  "version": "0.2.0",
  "description": "opencode TUI plugin: terminal-title tab indicator — braille spinner while a session works, blinking ? while the agent waits for your input (permission/question).",
  "type": "module",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts",
    "./tui": "./src/index.ts"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "dev": "bun run scripts/dev-sandbox.ts"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "terminal-title",
    "tab-indicator",
    "ghostty"
  ],
  "license": "MIT",
  "devDependencies": {
    "@opencode-ai/plugin": "^1.17.0",
    "@types/bun": "^1.1.0",
    "typescript": "^5"
  }
}
